<script setup lang="ts">
import { onMounted, ref } from 'vue'
import type { TrabajadorAsistencia } from '../interfaces/asistencia.interface'
import type { HorarioTrabajo, RegimenHorario } from '../interfaces/horario.interface'
import { descargarPlantillaAsistencias, guardarAsistencia, importarAsistencias, listarAsistencias } from '../services/asistencias'

const regimenes=ref<RegimenHorario[]>([]), horarios=ref<HorarioTrabajo[]>([]), rows=ref<TrabajadorAsistencia[]>([])
const regimenId=ref<number|null>(null), fecha=ref(new Date().toISOString().slice(0,10)), q=ref(''), page=ref(1), lastPage=ref(1), total=ref(0), from=ref<number|null>(null), to=ref<number|null>(null)
const loading=ref(false), savingId=ref<number|null>(null), importing=ref(false), downloading=ref(false), error=ref(''), success=ref(''), file=ref<File|null>(null)
const time=(v:string|null)=>v?.slice(0,5)??''
function normalize(row:TrabajadorAsistencia){row.asistencia.entrada_1=time(row.asistencia.entrada_1);row.asistencia.salida_1=time(row.asistencia.salida_1);row.asistencia.entrada_2=time(row.asistencia.entrada_2);row.asistencia.salida_2=time(row.asistencia.salida_2)}
async function load(next=1){loading.value=true;error.value='';try{const r=await listarAsistencias(regimenId.value,fecha.value,q.value,next);rows.value=r.data;rows.value.forEach(normalize);regimenes.value=r.regimenes;horarios.value=r.horarios;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;from.value=r.from;to.value=r.to}catch(e){error.value=e instanceof Error?e.message:'No se pudo consultar asistencias.'}finally{loading.value=false}}
async function save(row:TrabajadorAsistencia){if(!regimenId.value||!fecha.value)return;savingId.value=row.id;error.value='';success.value='';try{await guardarAsistencia({...row.asistencia,datos_persona_id:row.id,regimen_id:regimenId.value,fecha:fecha.value});success.value=`Asistencia de ${row.nombre_completo} actualizada.`}catch(e){error.value=e instanceof Error?e.message:'No se pudo guardar.'}finally{savingId.value=null}}
function selectFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]??null}
async function upload(){if(!file.value){error.value='Seleccione un archivo Excel o CSV.';return}importing.value=true;error.value='';success.value='';try{const r=await importarAsistencias(file.value,regimenId.value,fecha.value,q.value);success.value=r.message||'Asistencias importadas correctamente.';file.value=null;await load(1)}catch(e){error.value=e instanceof Error?e.message:'No se pudo importar el archivo.'}finally{importing.value=false}}
async function download(){downloading.value=true;error.value='';try{await descargarPlantillaAsistencias()}catch(e){error.value=e instanceof Error?e.message:'No se pudo descargar la plantilla.'}finally{downloading.value=false}}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/recursos">Recursos Humanos</RouterLink> / Asistencias</nav><header class="hero"><div class="mark">AS</div><div><small>MIA · RR. HH. · CONTROL DE TIEMPOS</small><h1>Asistencias</h1><p>Registra, corrige e importa las marcaciones diarias del personal.</p></div><button class="outline" :disabled="downloading" @click="download">{{downloading?'Descargando…':'Descargar plantilla'}}</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Régimen<select v-model="regimenId"><option :value="null">Todos los regímenes</option><option v-for="r in regimenes" :key="r.id" :value="r.id">{{r.codigo}} - {{r.descripcion}}</option></select></label><label>Fecha<input v-model="fecha" type="date"></label><label>Buscar<input v-model.trim="q" placeholder="Código, apellidos, nombres o DNI"></label><button>Consultar</button></form><section class="import"><div><b>Importar marcaciones</b><small>Columnas: codigo_trabajador, fecha, primera_entrada, primera_salida, segunda_entrada, segunda_salida</small></div><input type="file" accept=".xlsx,.xls,.csv" @change="selectFile"><button :disabled="importing||!file" @click="upload">{{importing?'Importando…':'Importar'}}</button></section><p class="info">El sistema toma el horario programado y clasifica la marcación como <b>TR</b> (completa) o <b>FA</b> (incompleta). Puede corregirse manualmente a <b>FJ</b>.</p><section class="card"><div v-if="loading" class="empty">Consultando asistencias…</div><div v-else-if="!rows.length" class="empty">Seleccione filtros y consulte, o no existen trabajadores para el criterio indicado.</div><div v-else class="scroll"><table><thead><tr><th>#</th><th>Código / Trabajador</th><th>Horario</th><th>Fecha</th><th>Tipo</th><th>1ª entrada</th><th>1ª salida</th><th>2ª entrada</th><th>2ª salida</th><th>Acción</th></tr></thead><tbody><tr v-for="(row,i) in rows" :key="row.id"><td>{{(from||1)+i}}</td><td><b>{{row.codigo_trabajador}}</b><small>{{row.nombre_completo}}</small></td><td><select v-model="row.asistencia.horario_id"><option :value="null">Sin horario</option><option v-for="h in horarios" :key="h.id" :value="h.id">{{h.codigo}} · {{h.descripcion}}</option></select></td><td><span class="date">{{fecha}}</span></td><td><select v-model="row.asistencia.tipo"><option value="TR">TR · Trabajo</option><option value="FA">FA · Falta</option><option value="FJ">FJ · Justificada</option></select></td><td><input v-model="row.asistencia.entrada_1" type="time"></td><td><input v-model="row.asistencia.salida_1" type="time"></td><td><input v-model="row.asistencia.entrada_2" type="time"></td><td><input v-model="row.asistencia.salida_2" type="time"></td><td><button :disabled="savingId===row.id||!fecha" @click="save(row)">{{savingId===row.id?'Guardando…':'Guardar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><small>{{from||0}}–{{to||0}} de {{total}}</small><div><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></div></footer></section></div></template>

<style scoped>
.page{padding:25px;min-height:100%;background:#f4f7fb;color:#18344f}nav{font-size:13px;margin-bottom:18px}nav a{color:#157f86}.hero{display:flex;align-items:center;gap:16px;padding:22px 25px;background:linear-gradient(125deg,#087f83,#13b99c);color:white;border-radius:15px;box-shadow:0 10px 25px #087f8330}.hero h1{margin:2px 0;font-size:27px}.hero p,.hero small{margin:0;opacity:.9}.mark{display:grid;place-items:center;width:55px;height:55px;border-radius:14px;background:#ffffff28;font-weight:800}.hero>button{margin-left:auto}.filters,.import{display:flex;gap:12px;align-items:end;margin-top:18px;padding:16px;background:white;border:1px solid #dbe5ec;border-radius:12px}.filters label{display:grid;gap:6px;flex:1;font-size:12px;font-weight:700}.filters label:nth-child(3){flex:1.5}.import{align-items:center}.import div{display:grid;gap:3px;margin-right:auto}.import small,td small{display:block;color:#718295;margin-top:3px}.info,.flash{padding:12px 15px;border-radius:9px}.info{background:#e9f7fa;color:#27606c}.success{background:#dcf8e8;color:#137145}.error{background:#ffe5e5;color:#a32a2a}input,select,button{min-height:38px;border:1px solid #cddbe5;border-radius:7px;padding:7px 9px;background:white;color:inherit}button{background:#087f83;color:white;border:0;font-weight:700;cursor:pointer}button:disabled{opacity:.55;cursor:not-allowed}.outline{background:white!important;color:#087f83!important;padding:0 15px}.card{margin-top:15px;background:white;border:1px solid #dbe5ec;border-radius:12px;overflow:hidden}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th{padding:12px 9px;background:#173f57;color:white;text-align:left;white-space:nowrap}td{padding:9px;border-bottom:1px solid #e7edf2;min-width:105px}td:nth-child(2){min-width:210px}td:nth-child(3){min-width:220px}td input,td select{width:100%;min-height:34px}.date{background:#e9f4f6;padding:5px 8px;border-radius:6px;white-space:nowrap}.empty{padding:38px;text-align:center;color:#758494}.card footer{display:flex;justify-content:space-between;align-items:center;padding:12px 15px}.card footer div{display:flex;align-items:center;gap:10px}@media(max-width:850px){.page{padding:14px}.hero{align-items:flex-start;flex-wrap:wrap}.hero>button{margin-left:0}.filters,.import{align-items:stretch;flex-direction:column}.filters label{width:100%}}
</style>
